  function wbOptions(){return {widthFt:Number($('foot-width').value),lengthFt:Number($('foot-length').value),levels:Number($('wb-levels').value),floorSystem:$('wb-floor-system').value,ewpType:$('wb-ewp').value,floorDepthIn:Number($('wb-floor-depth').value),spacingFt:Number($('wb-spacing').value),orientation:$('wb-orientation').value,wallHeightFt:Number($('wb-wall-height').value),studSize:$('wb-stud').value,studSpacingFt:Number($('wb-stud-spacing').value),addCenterBeam:$('wb-center-beam').checked,lvlType:$('wb-lvl').value,lvlPlies:Number($('wb-lvl-plies').value),floorDead:Number($('wb-floor-dead').value),floorLive:Number($('wb-floor-live').value),wallDead:Number($('wb-wall-dead').value)};}
  function renderBuilding(){if(!wholeBuilding){$('wb-results').innerHTML='<p class="help">Generate framing to create the whole-building model.</p>';return;}const floors=wholeBuilding.floors.reduce((s,f)=>s+f.members.length,0),studs=wholeBuilding.walls.reduce((s,w)=>s+w.studs,0),lp=wholeBuilding.loads,integ=validateWholeBuildingIntegration(wholeBuilding,api.get().assembly);$('wb-results').innerHTML=`<table><tbody><tr><th>Roof / floor / wall integration</th><td><strong>${integ.status}</strong></td></tr><tr><th>Floor framing members</th><td>${floors}</td></tr><tr><th>Wall panels</th><td>${wholeBuilding.walls.length}</td></tr><tr><th>Wall studs</th><td>${studs}</td></tr><tr><th>LVL beams</th><td>${wholeBuilding.beams.length}</td></tr><tr><th>Foundation gravity ledger</th><td>${lp?lp.foundationKN+' kN · '+lp.status:'Not calculated'}</td></tr></tbody></table><div class="help">${integ.checks.map(c=>`${c.ok?'✓':'⚠'} ${c.system}: ${c.detail}`).join('<br>')}</div>`;}
  $('wb-import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(/\.dxf$/i.test(f.name))buildingImport=parseBuildingDXF(await f.text(),'auto');else if(/\.obj$/i.test(f.name))buildingImport=parseBuildingOBJ(await f.text(),Number($('units').value),$('axis').value==='Y up');else throw Error('Whole-building IFC semantic extraction is not yet validated in this build. Use the existing IFC roof import, or export an architectural DXF with named layers for walls/floors/openings.');const q=importSummary(buildingImport);if(q.widthFt>0)$('foot-width').value=q.widthFt.toFixed(3);if(q.lengthFt>0)$('foot-length').value=q.lengthFt.toFixed(3);$('wb-import-status').textContent=`${f.name}: ${q.recognition}; ${q.walls} wall segments, ${q.openings} openings, ${q.floorOpenings} floor openings, ${q.beams} beams, ${q.posts} posts. Footprint ${q.widthFt.toFixed(2)} × ${q.lengthFt.toFixed(2)} ft. ${q.note}`;}catch(err){api.notify(err.message,true);buildingImport=null;}$('wb-import').value='';};
  $('wb-import-generate').onclick=()=>{if(!buildingImport){api.notify('Import a building DXF or OBJ first.',true);return;}wholeBuilding=buildWholeBuilding(wbOptions());wholeBuilding.importGeometry=buildingImport;wholeBuilding.importSummary=importSummary(buildingImport);const mapped=mapImportedOpenings(buildingImport,wholeBuilding.levels);applyWallOpenings(wholeBuilding,mapped);const fos=(buildingImport.floorOpenings||[]).map(o=>({...o,level:Math.min(2,wholeBuilding.levels)}));addFloorOpenings(wholeBuilding,fos);wholeBuilding.importWarnings=[];if(buildingImport.recognition==='envelope-only')wholeBuilding.importWarnings.push('OBJ supplied envelope only; wall/opening/floor semantics require review.');if(!(buildingImport.walls||[]).length)wholeBuilding.importWarnings.push('No layer-classified wall segments found; perimeter walls were generated from the imported envelope.');renderBuilding();$('wb-status').textContent=`Imported-building framing generated: ${mapped.length} openings mapped to perimeter walls and ${fos.length} floor openings applied. Review imported recognition before engineering use.`;};
  $('wb-generate').onclick=()=>{wholeBuilding=buildWholeBuilding(wbOptions());applyEWPFraming(wholeBuilding,{section:$('ewp-section').value,manufacturer:$('ewp-manufacturer').value,blockingSpacingFt:Number($('ewp-blocking').value),rimSection:$('ewp-rim').value});renderBuilding();$('wb-status').textContent='Floor/EWP and wall-panel framing model generated. Member capacities remain REVIEW until manufacturer/code data is supplied.';};
