  function ewp6Refresh(){if(!wholeBuilding)wholeBuilding=buildWholeBuilding(wbOptions());buildEWPV6Editor(wholeBuilding,{section:$('ewp-section').value,manufacturer:$('ewp-manufacturer').value,spacingFt:wholeBuilding.spacingFt,cantileverFt:Number($('ewp-cantilever').value)});const lvl=Number($('ewp6-level').value)||1,objs=ewpEditorObjects(wholeBuilding,lvl),sel=$('ewp6-member'),old=sel.value;sel.innerHTML=objs.map(o=>`<option value="${esc(o.id)}">${esc(o.kind)} · ${esc(o.id)} · ${esc(o.section)}</option>`).join('');if(objs.some(o=>o.id===old))sel.value=old;ewp6Load();const f=(wholeBuilding.floors||[]).find(x=>Number(x.level)===lvl),bars=(f?.ewp3D||[]).slice(0,120);$('ewp6-view').innerHTML=`<svg viewBox="0 0 900 220" style="width:100%;height:220px;background:#f8fafc">${bars.map((m,i)=>{const y=12+(i%18)*11,x=20+(Math.floor(i/18)%6)*140,w=Math.max(18,Math.min(120,m.lengthFt*4));return `<rect x="${x}" y="${y}" width="${w}" height="7" rx="2" fill="${m.shape==='I'?'#d7aa62':'#b9824d'}"><title>${esc(m.id)} · ${esc(m.section)} · ${m.lengthFt} ft</title></rect>`}).join('')}<text x="20" y="210" fill="#475569" font-size="12">Level ${lvl}: ${bars.length} physical EWP framing records · I-joists = flange/web solids · engineered beams = rectangular solids</text></svg>`;$('ewp6-status').textContent=`V6 editor ready: ${objs.length} editable framing members on Level ${lvl}.`;}
  function ewp6Load(){const o=ewpEditorObjects(wholeBuilding,Number($('ewp6-level').value)||1).find(x=>x.id===$('ewp6-member').value);if(!o)return;$('ewp6-section').value=o.section;$('ewp6-plies').value=o.plies||1;$('ewp6-pos').value=o.positionFt??0;const f=(wholeBuilding.floors||[]).find(x=>Number(x.level)===Number($('ewp6-level').value)),m=(f?.framingMembers||f?.members||[]).find(x=>x.id===o.id);$('ewp6-start').value=m?.startFt??0;$('ewp6-end').value=m?.endFt??o.spanFt;}
