 function templateOptions(t){
   const base=api.settings(),panels=Number($('panels').value);
   const ovhVal=Number($('roof-overhang')?.value||24);
   const ovhIn=ovhVal>72?ovhVal/25.4:ovhVal;
   const overhang=ovhIn*0.0254;
   if(!Number.isInteger(panels)||panels<2||panels>24||!Number.isFinite(overhang)||overhang<0||overhang>1.83)throw Error('Panel target must be 2–24; roof overhang must be 0–72 inches (0–1.83 m).');
   const shape=$('shape').value,style=$('web-style').value;
   return {panel:Math.min(base.panel,t.span/panels),shape,style:style==='Auto'?shapeWeb(shape):style,overhang};
 }
 function configureAssembly(a){for(const t of a.trusses){const o=templateOptions(t);t.members=templateMembers(t,o);t.shape=o.shape;t.webStyle=o.style;delete t.analysis;delete t.edited;}undo=[];picked=null;lastParameters=null;renderResults();updatePicked();}
