  const auto=autoDesignAssembly(s.assembly,p,{ids,skipInitial:true,optionsFor:templateOptions,styles:$('web-style').value==='Auto'?WEB_STYLES:[$('web-style').value]});   lastAuto=auto;lastParameters=p;
