  $('save-project').onclick=()=>{const s=api.get();download('cadtech-project.json',JSON.stringify({version:2,...s,settings:api.settings(),options:uiValues(),wallSegments},null,2),'application/json');};$('load-project').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>30*1024*1024)throw Error('Project exceeds 30 MB');const d=JSON.parse(await f.text());if(d.version!==2||!d.source||!Array.isArray(d.source.axes)||!d.assembly||!Array.isArray(d.assembly.trusses)||d.assembly.trusses.length>1500)throw Error('Choose a CadTech v2 saved project.');for(const t of d.assembly.trusses){if(typeof t.id!=='string'||!/^[-A-Za-z0-9_]{1,30}$/.test(t.id)||!['Common','Stepdown','Girder','Front jack','Side jack','Hip carrier','Mono','Unclassified'].includes(t.type)||![1,2,3,4].includes(t.ply)||!Array.isArray(t.members)||t.members.length>500||!Array.isArray(t.profile)||!Array.isArray(t.normal)||t.members.some(m=>!Array.isArray(m.a)||!Array.isArray(m.b)||[...m.a,...m.b].some(x=>!Number.isFinite(x))))throw Error('Invalid saved geometry');}applyValues(d.options);if(d.settings){$('heel').value=d.settings.heel*1000;$('panel').value=d.settings.panel*1000;$('hips').checked=!!d.settings.inferHips;}wallSegments=d.wallSegments||[];api.restore(d);lastParameters=d.assembly.trusses.some(t=>t.analysis)?parameters():null;undo=[];picked=null;updatePicked();renderResults();api.notify('Project restored, including source geometry and member edits.');}catch(e){api.notify(e.message,true);}$('load-project').value='';};
