 function refreshObjects(){const m=ensureBI(),objs=buildObjectIndex(m,api.get().assembly),sel=$('bo-object');const old=sel.value;sel.innerHTML=objs.map(o=>`<option value="${esc(o.id)}">${esc(o.type)} · ${esc(o.id)}</option>`).join('');if(objs.some(o=>o.id===old))sel.value=old;loadObject();return objs;}
 function loadObject(){const m=ensureBI(),o=objectProperties(m,api.get().assembly,$('bo-object').value);if(!o){$('bo-results').textContent='No structural object selected.';return;}$('bo-section').value=o.props.section||o.props.stud||'';$('bo-spacing').value=o.props.spacingFt||'';$('bo-height').value=o.props.heightFt||'';$('bo-plies').value=o.props.plies||o.props.ply||'';$('bo-bearing').checked=o.props.bearing!==false;$('bo-results').innerHTML=`<strong>${esc(o.type)} · ${esc(o.id)}</strong><br>Level ${esc(o.level??'—')} · ${esc(JSON.stringify(o.props))}`;}
