 let geSelected='',geDrag=null,geUndo=[],geRedo=[];
 function geCheckpoint(){geUndo.push(snapshotModel(ensureBI()));if(geUndo.length>10)geUndo.shift();geRedo=[];}
 function geCommit(id,reason){regenGraphic(id,reason);}
 function refreshGraphicalEditor(){const m=ensureBI(),level=Math.max(1,Number($('ge-level').value)||1);ensureEditableGeometry(m);const all=editorObjects(m,level),filter=$('ge-filter')?.value||'ALL',layer=$('ge-layer')?.value||'ALL',objs=all.filter(o=>(filter==='ALL'||o.type===filter)&&(layer==='ALL'||objectLayer(m,o.id)===layer)),sel=$('ge-object'),old=geSelected||sel.value;sel.innerHTML=objs.map(o=>`<option value="${esc(o.id)}">${esc(o.type)} · ${esc(o.id)}</option>`).join('');geSelected=objs.some(o=>o.id===old)?old:(objs[0]?.id||'');sel.value=geSelected;const tgt=$('ge-target');if(tgt){const tv=tgt.value;tgt.innerHTML=all.filter(o=>o.type==='wall'&&o.id!==geSelected).map(o=>`<option value="${esc(o.id)}">wall · ${esc(o.id)}</option>`).join('');if([...tgt.options].some(o=>o.value===tv))tgt.value=tv;}const q=planSVG(m,level,geSelected);$('ge-plan').innerHTML=q.svg;$('ge-status').textContent=`Level ${level}: ${objs.length}/${all.length} visible editable objects · filter ${filter} · layer ${layer}. ${geSelected?'Selected '+geSelected:'No object on this level.'}`;}
 function regenGraphic(id,reason='graphical edit'){const m=ensureBI();markDirty(m,[id],reason);const rec=regenerateAffected(m,api.get().assembly,[id]);renderBuilding();renderBI();refreshObjects();refreshGraphicalEditor();$('ge-status').textContent=`${id} updated · regeneration revision ${rec.revision} · ${rec.touched.length} linked objects reviewed · QA ${rec.qa}.`;}
 $('ge-refresh').onclick=refreshGraphicalEditor;$('ge-level').onchange=refreshGraphicalEditor;$('ge-filter').onchange=refreshGraphicalEditor;$('ge-layer').onchange=refreshGraphicalEditor;$('ge-object').onchange=()=>{geSelected=$('ge-object').value;refreshGraphicalEditor();};
