$('ge-undo').onclick=()=>{if(!geUndo.length)return;const m=ensureBI();geRedo.push(snapshotModel(m));restoreModel(m,geUndo.pop());renderBuilding();renderBI();refreshObjects();refreshGraphicalEditor();$('ge-status').textContent='Undo applied. Regenerate affected before engineering issue.';};
 $('ge-redo').onclick=()=>{if(!geRedo.length)return;const m=ensureBI();geUndo.push(snapshotModel(m));restoreModel(m,geRedo.pop());renderBuilding();renderBI();refreshObjects();refreshGraphicalEditor();$('ge-status').textContent='Redo applied.';};

 $('ge-resize').onclick=()=>{if(!geSelected)return;geCheckpoint();const m=ensureBI(),obj=editorObjects(m,Number($('ge-level').value)||1).find(x=>x.id===geSelected);let patch={};if(obj?.type==='wall')patch.lengthFt=Number($('ge-size').value);else if(obj?.type==='opening')patch={widthFt:Number($('ge-size').value),heightFt:Number($('ge-height').value),sillFt:Number($('ge-sill').value)};else if(obj?.type==='floor-opening')patch={widthFt:Number($('ge-size').value),lengthFt:Number($('ge-height').value)};const r=resizeObject(m,geSelected,patch);if(!r){$('ge-status').textContent='Resize applies to walls and wall/floor openings.';return;}regenGraphic(geSelected,'graphical resize');};
 $('ge-regen').onclick=()=>{if(geSelected)regenGraphic(geSelected,'manual graphical regeneration');};
 $('ge-plan').addEventListener('pointerdown',e=>{const el=e.target.closest('[data-edit-id]');if(!el)return;geSelected=el.dataset.editId;$('ge-object').value=geSelected;const svg=$('ge-plan'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());geCheckpoint();geDrag={id:geSelected,x:p.x,y:p.y,moved:false};svg.setPointerCapture(e.pointerId);refreshGraphicalEditor();});
 $('ge-plan').addEventListener('pointermove',e=>{if(!geDrag)return;const svg=$('ge-plan'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse()),m=ensureBI(),q=planSVG(m,Number($('ge-level').value)||1,geSelected),dx=(p.x-geDrag.x)/q.scale,dy=-(p.y-geDrag.y)/q.scale;if(Math.hypot(dx,dy)<.03)return;let sx=dx,sy=dy;if($('ge-snap').checked)[sx,sy]=snapDelta(dx,dy,Number($('ge-grid').value),$('ge-ortho').checked);if(!sx&&!sy)return;moveObject(m,geDrag.id,sx,sy);geDrag.x=p.x;geDrag.y=p.y;geDrag.moved=true;const v=planSVG(m,Number($('ge-level').value)||1,geSelected);svg.innerHTML=v.svg;});
 $('ge-plan').addEventListener('pointerup',e=>{if(!geDrag)return;const d=geDrag;geDrag=null;if(d.moved)regenGraphic(d.id,'plan drag');else refreshGraphicalEditor();});$('ge-plan').addEventListener('pointercancel',()=>geDrag=null);

